void countWord(const std::string& filename, const std::string& word) {
    std::ifstream file(filename);
    if (!file) {
        std::cerr << "Error: cannot open file" << std::endl;
        return;
    }

    std::string line;
    unsigned int count = 0;
    while (std::getline(file, line)) {
